// Records exchanged with the Rust side. The JSON the bundled Afterhours.exe
// prints (`status --json`, `check --json`) is generated from schemas/ into
// ./generated by `pnpm types`; the rest mirrors src-tauri/src.

export type { State as SessionState, Status, StatusReport } from "./generated/status";
export type { Preflight } from "./generated/check";
export type { VersionReport } from "./generated/version";
export type { SettingsReport } from "./generated/settings";
export type { MapImagesReport } from "./generated/map-images";
import type { Event as SessionEvent } from "./generated/event";
export type { SessionEvent };
export type { MapCar, MapDriver, MapWorld, TrafficRing } from "./generated/event";
/** A `map-feed` event of `--events`: where the cars are (capability `map-feed`). */
export type MapFeed = Extract<SessionEvent, { event: "map-feed" }>;
export type {
  Car,
  CarImage,
  CarImages,
  CarLocation,
  CarSummary,
  Cell,
  Columns,
  Counts,
  Profile,
  Reputation,
  Save,
} from "./generated/profile";
export type { ProfileEntry, ProfileList } from "./generated/profile-list";
export type {
  CrashDump,
  ServerLog,
  SessionFile,
  SessionList,
  SessionSummary,
  UnsupportedRoute,
} from "./generated/sessions";

/** One session file as the log viewer reads it (src-tauri/src/reads.rs). */
export interface SessionFileText {
  name: string;
  bytes: number;
  text: string;
  truncated: boolean;
}

export type CliResult =
  { kind: "ok"; value: unknown } | { kind: "error"; exit: number; message: string };

export type UpdateMode = "ask" | "auto" | "off";

export interface UpdateSettings {
  mode: UpdateMode;
  skipped_version: string | null;
}

export interface Settings {
  game_dir: string | null;
  data_dir: string | null;
  player_name: string | null;
  avatar: string | null;
  first_run_done: boolean;
  updates: UpdateSettings;
  last_server_tag: string | null;
  /** Your server on another PC on your network; `null` is this PC's own. */
  server: RemoteServer | null;
}

/** A server on another PC: what its `api --json` prints there. */
export interface RemoteServer {
  /** `http://<IPv4 address>:<port>`. */
  url: string;
  /** Its API token, 64 lowercase hexadecimal characters. */
  token: string;
}

export type OutputLine =
  { kind: "status"; time: string; state: string; message: string } | { kind: "text"; text: string };

export type SessionAction = "setup" | "serve" | "start";

/** `status --json` as the server answered it. */
export type StatusProbe = { kind: "ok"; state: string } | { kind: "error"; message: string };

/** The current session as the data directory's records describe it. */
export type Recorded =
  | { kind: "none" }
  | {
      kind: "session";
      id: string;
      state: string;
      message: string;
      utc: string;
      /** Probed only for a live state; null when it could not be. */
      lock_held: boolean | null;
    }
  | { kind: "error"; message: string };

export interface Activity {
  cli: StatusProbe;
  recorded: Recorded;
  window_session: boolean;
}

export interface BackedUpFile {
  path: string;
  bytes: number;
  sha256: string;
}

export interface BackupReport {
  folder: string | null;
  files: BackedUpFile[];
}

export interface ServerInfo {
  repository: string;
  pinned_tag: string;
  pinned_sha256: string;
  override_allowed: boolean;
  path: string | null;
  source: "bundled" | "override" | null;
  version_line: string | null;
  matches_pin: boolean | null;
  /** From `version --json`; null for servers without it (v0.3.0). */
  capabilities: string[] | null;
  error: string | null;
}

export interface AppInfo {
  launcher_version: string;
  server: ServerInfo;
  data_dir: string | null;
  /** The launcher's own folder when it holds the game: then the game folder in use. */
  game_in_launcher_folder: string | null;
  updater: {
    endpoint: string | null;
    configured: boolean;
    /** Running from the no-install ZIP: updates open their download page. */
    portable: boolean;
  };
  debug_build: boolean;
  /** The signed-in user's name, for "Hide my user name"; `null` when unknown. */
  user_name: string | null;
}

export type Folder = "data" | "session" | "backups";

export function emptySettings(): Settings {
  return {
    game_dir: null,
    data_dir: null,
    player_name: null,
    avatar: null,
    first_run_done: false,
    updates: { mode: "ask", skipped_version: null },
    last_server_tag: null,
    server: null,
  };
}
